-- SinfQuiz 7.22. Run after the existing SinfQuiz schema. No Cron or secret key required.
begin;
create table if not exists public.sq_competitions(
 id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id),
 title text not null check(length(btrim(title)) between 4 and 100),description text not null default '' check(length(description)<=800),
 visibility text not null default 'public' check(visibility in ('public','code')),team_size integer not null check(team_size between 1 and 12),
 status text not null default 'draft' check(status in ('draft','lobby','running','finished','cancelled')),
 current_stage integer not null default 0,stage_started_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table if not exists public.sq_comp_teams(
 id uuid primary key default gen_random_uuid(),competition_id uuid not null references public.sq_competitions(id) on delete cascade,
 title text not null check(length(btrim(title)) between 2 and 60),join_code text not null unique check(join_code ~ '^[A-F0-9]{8}$'),
 roster jsonb not null default '[]' check(jsonb_typeof(roster)='array'),unique(competition_id,title),unique(id,competition_id)
);
create table if not exists public.sq_comp_members(
 competition_id uuid not null references public.sq_competitions(id) on delete cascade,user_id uuid not null references auth.users(id),
 team_id uuid not null,seat integer not null check(seat between 1 and 12),name text not null check(length(btrim(name)) between 2 and 40),withdrawn boolean not null default false,
 joined_at timestamptz not null default now(),primary key(competition_id,user_id),unique(team_id,seat),
 foreign key(team_id,competition_id) references public.sq_comp_teams(id,competition_id) on delete cascade
);
create table if not exists public.sq_comp_stages(
 id uuid primary key default gen_random_uuid(),competition_id uuid not null references public.sq_competitions(id) on delete cascade,
 position integer not null check(position between 1 and 24),title text not null check(length(btrim(title)) between 3 and 100),
 kind text not null check(kind in ('quiz','typing','maze')),duration integer not null check(duration between 30 and 3600),weight integer not null check(weight between 1 and 10),
 config jsonb not null,data jsonb not null check(length(data::text)<=200000),unique(competition_id,position)
);
create table if not exists public.sq_comp_attempts(
 competition_id uuid not null,stage_id uuid not null references public.sq_comp_stages(id) on delete cascade,user_id uuid not null,
 started_at timestamptz not null,finished_at timestamptz,cursor integer not null default 0,correct integer not null default 0,
 points numeric not null default 0,score numeric not null default 0 check(score between 0 and 100),elapsed numeric not null default 0,
 payload jsonb not null default '{}',actions jsonb not null default '{}',feedback jsonb,primary key(stage_id,user_id),
 foreign key(competition_id,user_id) references public.sq_comp_members(competition_id,user_id) on delete cascade
);
create table if not exists public.sq_comp_templates(id text primary key,kind text not null check(kind in ('quiz','typing','maze')),title text not null,data jsonb not null);
create table if not exists public.sq_comp_limits(user_id uuid not null references auth.users(id) on delete cascade,kind text not null,bucket timestamptz not null,hits integer not null,primary key(user_id,kind,bucket));
create table if not exists public.sq_comp_signals(competition_id uuid primary key references public.sq_competitions(id) on delete cascade,revision bigint not null default 0,changed_at timestamptz not null default now());
create index if not exists sq_comp_owner_idx on public.sq_competitions(owner_id,updated_at desc);
create index if not exists sq_comp_status_idx on public.sq_competitions(status,visibility);
create index if not exists sq_comp_team_members_idx on public.sq_comp_members(team_id);
create index if not exists sq_comp_attempt_comp_idx on public.sq_comp_attempts(competition_id,stage_id);
create index if not exists sq_comp_limits_bucket_idx on public.sq_comp_limits(bucket);

create or replace function public.sq_comp_owner(p_id uuid) returns boolean language sql stable security definer set search_path='' as $$
 select auth.uid() is not null and exists(select 1 from public.sq_competitions c where c.id=p_id and (c.owner_id=auth.uid() or public.sq_is_admin()))
$$;
create or replace function public.sq_comp_read(p_id uuid) returns boolean language sql stable security definer set search_path='' as $$
 select auth.uid() is not null and exists(select 1 from public.sq_competitions c where c.id=p_id and (
 c.owner_id=auth.uid() or public.sq_is_admin() or (c.visibility='public' and c.status in ('lobby','running')) or exists(select 1 from public.sq_comp_members m where m.competition_id=c.id and m.user_id=auth.uid())))
$$;
create or replace function public.sq_comp_tick(p_id uuid) returns void language sql security definer set search_path='' as $$
 insert into public.sq_comp_signals as sig(competition_id,revision,changed_at) values(p_id,1,clock_timestamp())
 on conflict(competition_id) do update set revision=sig.revision+1,changed_at=excluded.changed_at
$$;
create or replace function public.sq_comp_limit(p_kind text,p_max integer) returns boolean language plpgsql security definer set search_path='' as $$
 declare n integer;
 begin
  if auth.uid() is null then return false;end if;
  delete from public.sq_comp_limits l where l.user_id=auth.uid() and l.bucket<now()-interval '2 days';
  insert into public.sq_comp_limits as limits(user_id,kind,bucket,hits) values(auth.uid(),p_kind,date_trunc('minute',clock_timestamp()),1)
  on conflict(user_id,kind,bucket) do update set hits=limits.hits+1 returning hits into n;
  return n<=p_max;
 end
$$;
create or replace function public.sq_comp_norm(p_text text) returns text language sql immutable set search_path='' as $$
 select lower(btrim(regexp_replace(translate(coalesce(p_text,''),'“”‘’`ʻʼ',repeat(chr(39),7)),'\s+',' ','g')))
$$;
create or replace function public.sq_comp_shortcut(p_text text) returns text language sql immutable set search_path='' as $$
 select string_agg(k,'+' order by k) from (select distinct case btrim(v) when 'control' then 'ctrl' when 'command' then 'meta' when 'cmd' then 'meta' when 'escape' then 'esc' else btrim(v) end k from unnest(string_to_array(lower(coalesce(p_text,'')),'+')) v where btrim(v)<>'') keys
$$;

-- A bounded arithmetic parser; student text is never executed as SQL or JavaScript.
create or replace function public.sq_comp_excel(p_cells jsonb,p_address text,p_seen text[] default '{}') returns numeric language plpgsql set search_path='' as $$
 declare raw text;tokens text[];r jsonb;
 begin
  if p_address=any(p_seen) or cardinality(p_seen)>16 then raise exception 'Aylanma katak havolasi';end if;
  raw:=upper(regexp_replace(coalesce(p_cells->>p_address,''),'\s','','g'));
  if raw='' then return 0;end if;
  if left(raw,1)<>'=' then if raw ~ '^[+-]?[0-9]+(\.[0-9]+)?$' then return raw::numeric;else raise exception 'Sonli katak kerak';end if;end if;
  raw:=substr(raw,2);if length(raw)>120 then raise exception 'Formula juda uzun';end if;
  select array_agg(v[1]) into tokens from regexp_matches(raw,'(AVERAGE|SUM|[A-D][1-8]|[0-9]+(?:\.[0-9]+)?|[()+*/,:-])','g') v;
  if cardinality(tokens)>80 or array_to_string(tokens,'') is distinct from raw then raise exception 'Formula noto‘g‘ri';end if;
  r:=public.sq_comp_expr(tokens,1,0,p_cells,array_append(p_seen,p_address));
  if (r->>'next')::integer<=cardinality(tokens) then raise exception 'Formula oxirida ortiqcha belgi';end if;
  return (r->>'value')::numeric;
 end
$$;
create or replace function public.sq_comp_expr(p_tokens text[],p_at integer,p_min integer,p_cells jsonb,p_seen text[]) returns jsonb language plpgsql set search_path='' as $$
 declare i integer:=p_at;tok text;v numeric;r jsonb;prec integer;op text;vals numeric[]:='{}';a text;b text;col integer;rowno integer;addr text;raw text;
 begin
  tok:=p_tokens[i];i:=i+1;
  if tok in ('+','-') then r:=public.sq_comp_expr(p_tokens,i,3,p_cells,p_seen);v:=(r->>'value')::numeric;if tok='-' then v:=-v;end if;i:=(r->>'next')::integer;
  elsif tok='(' then r:=public.sq_comp_expr(p_tokens,i,0,p_cells,p_seen);v:=(r->>'value')::numeric;i:=(r->>'next')::integer;if p_tokens[i] is distinct from ')' then raise exception 'Qavs yopilmagan';end if;i:=i+1;
  elsif tok in ('SUM','AVERAGE') then
   if p_tokens[i] is distinct from '(' or p_tokens[i+2] is distinct from ':' or p_tokens[i+4] is distinct from ')' then raise exception 'Funksiya oralig‘i noto‘g‘ri';end if;
   a:=p_tokens[i+1];b:=p_tokens[i+3];i:=i+5;
   if a !~ '^[A-D][1-8]$' or b !~ '^[A-D][1-8]$' or ascii(a)>ascii(b) or substr(a,2)::integer>substr(b,2)::integer then raise exception 'Katak oralig‘i noto‘g‘ri';end if;
   for rowno in substr(a,2)::integer..substr(b,2)::integer loop for col in ascii(a)..ascii(b) loop
    addr:=chr(col)||rowno;raw:=btrim(coalesce(p_cells->>addr,''));
    if raw ~ '^[+-]?[0-9]+(\.[0-9]+)?$' or left(raw,1)='=' then vals:=array_append(vals,public.sq_comp_excel(p_cells,addr,p_seen));end if;
   end loop;end loop;
   select coalesce(sum(x),0) into v from unnest(vals) x;
   if tok='AVERAGE' then if cardinality(vals)=0 then raise exception 'O‘rtacha uchun son yo‘q';end if;v:=v/cardinality(vals);end if;
  elsif tok ~ '^[A-D][1-8]$' then v:=public.sq_comp_excel(p_cells,tok,p_seen);
  elsif tok ~ '^[0-9]+(\.[0-9]+)?$' then v:=tok::numeric;
  else raise exception 'Formula belgisi noto‘g‘ri';end if;
  loop
   op:=p_tokens[i];prec:=case when op in ('+','-') then 1 when op in ('*','/') then 2 else -1 end;exit when prec<p_min;
   r:=public.sq_comp_expr(p_tokens,i+1,prec+1,p_cells,p_seen);i:=(r->>'next')::integer;
   v:=case op when '+' then v+(r->>'value')::numeric when '-' then v-(r->>'value')::numeric when '*' then v*(r->>'value')::numeric else v/(r->>'value')::numeric end;
  end loop;
  return jsonb_build_object('value',v,'next',i);
 end
$$;

create or replace function public.sq_comp_grade(p_q jsonb,p_answer jsonb) returns jsonb language plpgsql set search_path='' as $$
 <<assessment>>
 declare ratio numeric:=0;checks jsonb:='[]';value text:=coalesce(p_answer#>>'{}','');sub jsonb;item jsonb;ok boolean;formula text;key text;n integer:=0;passed integer:=0;kind text:=p_q->>'type';
 begin
  if length(p_answer::text)>20000 then return jsonb_build_object('ratio',0,'checks','[]'::jsonb);end if;
  if kind='test' then ratio:=case when p_answer=p_q->'correct' then 1 else 0 end;
  elsif kind='shortcut' then ratio:=case when public.sq_comp_shortcut(value)=public.sq_comp_shortcut(p_q->>'answer') then 1 else 0 end;
  elsif kind='python' then
   begin sub:=value::jsonb;exception when others then sub:='{}';end;
   ratio:=case when length(btrim(coalesce(sub->>'code',''))) between 5 and 8000 and btrim(coalesce(sub->>'output',''))<>'' and public.sq_comp_norm(sub->>'output')=public.sq_comp_norm(p_q->>'answer') then 1 else 0 end;
  elsif kind='prompt' then
   for item in select x from jsonb_array_elements(coalesce(p_q->'criteria','[]')) x loop
    select exists(select 1 from jsonb_array_elements_text(item->'keywords') k where public.sq_comp_norm(k)<>'' and position(public.sq_comp_norm(k) in public.sq_comp_norm(assessment.value))>0) into ok;
    checks:=checks||jsonb_build_array(jsonb_build_object('label',item->>'label','passed',ok));n:=n+1;if ok then passed:=passed+1;end if;
   end loop;ratio:=passed::numeric/greatest(n,1);
  elsif kind='office' then
   begin sub:=value::jsonb;exception when others then sub:='{}';end;
   if sub->>'kind' is not distinct from p_q->'officeTask'->>'kind' then
    for item in select x from jsonb_array_elements(coalesce(p_q->'officeRubric',p_q->'officeTask'->'rubric','[]')) x loop
     ok:=false;
     begin
      if item->>'kind'='excelCell' then ok:=public.sq_comp_norm(sub->'cells'->>(item->>'cell'))=public.sq_comp_norm(item->>'value');
      elsif item->>'kind'='excelFormula' then
       formula:=upper(regexp_replace(coalesce(sub->'cells'->>(item->>'cell'),''),'\s','','g'));
       ok:=left(formula,1)='=' and (not (item?'fn') or position((item->>'fn')||'(' in formula)>0) and not exists(select 1 from jsonb_array_elements_text(coalesce(item->'references','[]')) ref where position(ref in formula)=0) and abs(public.sq_comp_excel(sub->'cells',item->>'cell')-(item->>'expected')::numeric)<.001;
      elsif item->>'kind'='wordText' then ok:=length(btrim(coalesce(sub->>'title',''))) between 3 and 1000 and length(btrim(coalesce(sub->>'body',''))) between 3 and 1000;
      elsif item->>'kind'='wordTable' then ok:=jsonb_array_length(sub->'table')>=2 and not exists(select 1 from jsonb_array_elements(sub->'table') with ordinality rows(x,i) where i<=2 and (jsonb_array_length(x)<2 or length(btrim(coalesce(x->>0,''))) not between 1 and 100 or length(btrim(coalesce(x->>1,''))) not between 1 and 100));
      elsif item->>'kind'='wordImage' then ok:=sub->'imageInserted'='true'::jsonb;
      elsif item->>'kind'='wordWrap' then ok:=sub->'imageInserted'='true'::jsonb and sub->>'wrap'=item->>'value';
      elsif item->>'kind'='wordReference' then ok:=not exists(select 1 from unnest(array['recipient','date','source']) f where length(btrim(coalesce(sub->'reference'->>f,''))) not between 3 and 1000);
      elsif item->>'kind'='pptSlides' then ok:=jsonb_array_length(sub->'slides')>=2 and sub->'slides'->0->>'title'<>sub->'slides'->1->>'title' and not exists(select 1 from jsonb_array_elements(sub->'slides') with ordinality slides(x,i) where i<=2 and (length(btrim(coalesce(x->>'title',''))) not between 3 and 1000 or length(btrim(coalesce(x->>'body',''))) not between 3 and 1000));
      elsif item->>'kind'='pptImage' then ok:=exists(select 1 from jsonb_array_elements(sub->'slides') slide where slide->'imageInserted'='true'::jsonb);
      elsif item->>'kind'='pptNotes' then ok:=length(btrim(coalesce(sub->'slides'->1->>'notes',''))) between 3 and 1000;
      end if;
     exception when others then ok:=false;end;
     checks:=checks||jsonb_build_array(jsonb_build_object('label',item->>'label','passed',coalesce(ok,false)));n:=n+1;if ok then passed:=passed+1;end if;
    end loop;
   end if;ratio:=passed::numeric/greatest(n,1);
  else
   for item in select x from jsonb_array_elements(jsonb_build_array(p_q->'answer')||coalesce(p_q->'acceptedAnswers','[]')) x loop
    if (case when p_q->>'subject'='Excel' then replace(public.sq_comp_norm(assessment.value),' ','')=replace(public.sq_comp_norm(item#>>'{}'),' ','') else public.sq_comp_norm(assessment.value)=public.sq_comp_norm(item#>>'{}') end) then ratio:=1;exit;end if;
   end loop;
  end if;
  return jsonb_build_object('ratio',ratio,'checks',checks);
 end
$$;

create or replace function public.sq_comp_prepare(p_stage jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
 <<source>>
 declare src jsonb;entry jsonb;qs jsonb:='[]';task jsonb;source_kind text:=p_stage->>'sourceKind';source_id text:=p_stage->>'sourceId';kind text:=p_stage->>'kind';i integer:=0;
 begin
  if not coalesce(public.sq_is_teacher(),false) then raise exception 'Faqat ustoz musobaqa tuzadi';end if;
  if source_kind='quiz' then
   select q.data into src from public.documents q where q.collection='quizzes' and q.id=source_id and (q.data->>'ownerId'=auth.uid()::text or q.data->>'visibility'='public' or public.sq_is_admin());
   if src is null or kind<>'quiz' then raise exception 'Bu testni biriktirishga ruxsat yo‘q';end if;
  elsif source_kind='maze' then
   select q.data into src from public.documents q where q.collection='audioMazeLevels' and q.id=source_id and (q.data->>'ownerId'=auth.uid()::text or q.data->>'approvalStatus'='approved' or public.sq_is_admin());
   if src is null or kind<>'maze' then raise exception 'Bu labirintni biriktirishga ruxsat yo‘q';end if;
   select t.data into task from public.sq_comp_templates t where t.id='maze:'||coalesce(src->>'mapId','maze-01');
   src:=task||src;
  elsif source_kind='template' then
   select t.data into src from public.sq_comp_templates t where t.id=source_id and t.kind=source.kind and t.id not like 'office:%';
  elsif source_kind='custom' then src:=p_stage->'custom';
  else raise exception 'Bosqich manbasi noto‘g‘ri';end if;
  if src is null or jsonb_typeof(src)<>'object' or length(src::text)>200000 then raise exception 'Bosqich mazmuni to‘liq emas';end if;
  if kind='quiz' then
   if jsonb_typeof(src->'questions') is distinct from 'array' or jsonb_array_length(src->'questions') not between 1 and 50 then raise exception 'Testda 1–50 savol bo‘lsin';end if;
   for entry in select x from jsonb_array_elements(src->'questions') x loop
    i:=i+1;
    if length(btrim(coalesce(entry->>'text',''))) not between 3 and 2000 or coalesce(entry->>'type','') not in ('test','practical','shortcut','office','python','prompt') then raise exception 'Savol matni yoki turi noto‘g‘ri';end if;
    if entry->>'type'='test' then
     if jsonb_typeof(entry->'options') is distinct from 'array' or jsonb_array_length(entry->'options') not between 2 and 6 or coalesce(entry->>'correct','') !~ '^[0-5]$' or (entry->>'correct')::integer>=jsonb_array_length(entry->'options') or exists(select 1 from jsonb_array_elements_text(entry->'options') op where length(btrim(op)) not between 1 and 500) then raise exception 'Savol variantlari yoki javobi noto‘g‘ri';end if;
    elsif entry->>'type'='office' then
     task:=entry->'officeTask';if task is null then select t.data->'officeTask' into task from public.sq_comp_templates t where t.id='office:'||(entry->>'officeTemplate');end if;
     if task->>'kind' not in ('word','excel','ppt') or jsonb_typeof(task->'rubric') is distinct from 'array' or jsonb_array_length(task->'rubric') not between 1 and 20 then raise exception 'Office mashqi sozlanmagan';end if;
     entry:=entry||jsonb_build_object('officeTask',task);
    elsif entry->>'type'='prompt' then
     if jsonb_typeof(entry->'criteria') is distinct from 'array' or jsonb_array_length(entry->'criteria') not between 1 and 20 then raise exception 'Prompt mezonlari kerak';end if;
     if exists(select 1 from jsonb_array_elements(entry->'criteria') r where jsonb_typeof(r) is distinct from 'object' or jsonb_typeof(r->'keywords') is distinct from 'array' or jsonb_array_length(r->'keywords') not between 1 and 20 or length(btrim(coalesce(r->>'label',''))) not between 1 and 200) then raise exception 'Har mezonda nom va kalit iboralar kerak';end if;
     if exists(select 1 from jsonb_array_elements(entry->'criteria') r cross join lateral jsonb_array_elements_text(r->'keywords') k where length(btrim(k)) not between 1 and 200) then raise exception 'Kalit iboralar bo‘sh yoki juda uzun';end if;
    elsif length(btrim(coalesce(entry->>'answer',''))) not between 1 and 8000 then raise exception 'Namuna javobni kiriting';end if;
    if coalesce(entry->>'points','100') !~ '^[0-9]{1,5}$' or coalesce(entry->>'points','100')::integer not between 10 and 10000 then raise exception 'Savol bali noto‘g‘ri';end if;
    qs:=qs||jsonb_build_array(entry||jsonb_build_object('id','q-'||i,'points',coalesce(entry->>'points','100')::integer));
   end loop;src:=jsonb_build_object('questions',qs);
  elsif kind='typing' then
   if length(btrim(coalesce(src->>'text',''))) not between 20 and 4000 then raise exception 'Typing matni 20–4000 belgidan iborat bo‘lsin';end if;
   src:=jsonb_build_object('text',src->>'text','level',coalesce(src->>'level',src->>'englishLevel','Matn'),'language',coalesce(src->>'language','uz'));
  elsif kind='maze' then
   if jsonb_typeof(src->'grid') is distinct from 'array' or jsonb_array_length(src->'grid') not between 9 and 31 or jsonb_typeof(src->'tasks') is distinct from 'array' or jsonb_array_length(src->'tasks') not between 5 and 8 or jsonb_array_length(src->'gateCells')<>jsonb_array_length(src->'tasks') then raise exception 'Labirint xaritasi va savollari mos emas';end if;
   for entry in select x from jsonb_array_elements(src->'tasks') x loop
    if length(btrim(coalesce(entry->>'audio',''))) not between 3 and 500 or jsonb_array_length(entry->'options') not between 2 and 6 or coalesce(entry->>'answer','') !~ '^[0-5]$' or (entry->>'answer')::integer>=jsonb_array_length(entry->'options') then raise exception 'Labirint savoli noto‘g‘ri';end if;
   end loop;
  else raise exception 'Bosqich turi noto‘g‘ri';end if;
  return src;
 end
$$;

create or replace function public.sq_comp_catalog() returns jsonb language plpgsql security definer set search_path='' as $$
 declare sources jsonb;
 begin
  if auth.uid() is null or not coalesce(public.sq_is_teacher(),false) then raise exception 'Ustoz sifatida kiring';end if;
  select coalesce(jsonb_agg(item order by sort,title),'[]') into sources from (
   select 0 sort,q.data->>'title' title,jsonb_build_object('sourceKind','quiz','sourceId',q.id,'kind','quiz','title',q.data->>'title','subtitle',coalesce(q.data->>'pin','')||' · '||coalesce(q.data->>'subject','Test'),'count',jsonb_array_length(q.data->'questions'),'owner',coalesce(q.data->>'ownerName','Ustoz')) item
   from public.documents q where q.collection='quizzes' and jsonb_typeof(q.data->'questions')='array' and (q.data->>'ownerId'=auth.uid()::text or q.data->>'visibility'='public' or public.sq_is_admin())
   union all
   select 1 sort,t.title,jsonb_build_object('sourceKind','template','sourceId',t.id,'kind',t.kind,'title',t.title,'subtitle',coalesce(t.data->>'englishLevel',t.data->>'difficulty',t.data->>'level','Tayyor material'),'count',case t.kind when 'quiz' then jsonb_array_length(t.data->'questions') when 'maze' then jsonb_array_length(t.data->'tasks') else length(t.data->>'text') end,'owner','SinfQuiz')
   from public.sq_comp_templates t where t.id not like 'office:%'
   union all
   select 2 sort,q.data->>'title',jsonb_build_object('sourceKind','maze','sourceId',q.id,'kind','maze','title',q.data->>'title','subtitle','Ustoz labirinti','count',jsonb_array_length(q.data->'tasks'),'owner',q.data->>'ownerName')
   from public.documents q where q.collection='audioMazeLevels' and (q.data->>'ownerId'=auth.uid()::text or q.data->>'approvalStatus'='approved' or public.sq_is_admin())
  ) catalog;
  return jsonb_build_object('sources',sources);
 end
$$;

create or replace function public.sq_comp_save(p_id uuid,p_config jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
 declare old public.sq_competitions;stage jsonb;team jsonb;data jsonb;i integer:=0;size integer;code text;roster jsonb;owner uuid;
 begin
  if auth.uid() is null or not coalesce(public.sq_is_teacher(),false) then raise exception 'Ustoz sifatida kiring';end if;
  if length(p_config::text)>350000 or jsonb_typeof(p_config->'stages') is distinct from 'array' or jsonb_array_length(p_config->'stages') not between 4 and 24 or jsonb_typeof(p_config->'teams') is distinct from 'array' or jsonb_array_length(p_config->'teams') not between 2 and 32 then raise exception 'Kamida 4 bosqich va 2 jamoa kerak';end if;
  if coalesce(p_config->>'teamSize','') !~ '^[0-9]{1,2}$' then raise exception 'Jamoa hajmini kiriting';end if;size:=(p_config->>'teamSize')::integer;
  select c.* into old from public.sq_competitions c where c.id=p_id for update;
  if found then if not public.sq_comp_owner(p_id) then raise exception 'Begona musobaqani o‘zgartirish mumkin emas';end if;if old.status<>'draft' then raise exception 'Faollashtirilgan musobaqaning tarkibi o‘zgarmaydi';end if;owner:=old.owner_id;
  else owner:=auth.uid();end if;
  insert into public.sq_competitions(id,owner_id,title,description,team_size,visibility) values(p_id,owner,btrim(p_config->>'title'),coalesce(p_config->>'description',''),size,coalesce(p_config->>'visibility','public')) on conflict(id) do update set title=excluded.title,description=excluded.description,team_size=excluded.team_size,visibility=excluded.visibility,updated_at=clock_timestamp();
  delete from public.sq_comp_stages s where s.competition_id=p_id;delete from public.sq_comp_teams t where t.competition_id=p_id;
  for team in select x from jsonb_array_elements(p_config->'teams') x loop
   roster:=coalesce(team->'roster','[]');
   if jsonb_array_length(roster) not in (0,size) or exists(select 1 from jsonb_array_elements_text(roster) n where length(btrim(n)) not between 2 and 40) or (select count(distinct public.sq_comp_norm(n)) from jsonb_array_elements_text(roster) n)<>jsonb_array_length(roster) then raise exception 'Ro‘yxat bo‘sh yoki jamoa hajmiga teng, ismlar esa farqli bo‘lsin';end if;
   loop
    code:=upper(substr(replace(gen_random_uuid()::text,'-',''),1,8));
    exit when not exists(select 1 from public.sq_comp_teams t where t.join_code=code);
   end loop;
   insert into public.sq_comp_teams(competition_id,title,join_code,roster) values(p_id,btrim(team->>'title'),code,roster);
  end loop;
  for stage in select x from jsonb_array_elements(p_config->'stages') x loop
   i:=i+1;data:=public.sq_comp_prepare(stage);
   insert into public.sq_comp_stages(competition_id,position,title,kind,duration,weight,config,data) values(p_id,i,btrim(stage->>'title'),stage->>'kind',(stage->>'duration')::integer,(stage->>'weight')::integer,stage-'custom',data);
  end loop;
  perform public.sq_comp_tick(p_id);return jsonb_build_object('id',p_id);
 end
$$;

create or replace function public.sq_comp_list() returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('competitions',coalesce(jsonb_agg(item order by changed desc),'[]')) from (
  select c.updated_at changed,jsonb_build_object('id',c.id,'title',c.title,'description',c.description,'status',c.status,'teamSize',c.team_size,'currentStage',c.current_stage,'stageCount',(select count(*) from public.sq_comp_stages s where s.competition_id=c.id),'teamCount',(select count(*) from public.sq_comp_teams t where t.competition_id=c.id),'memberCount',(select count(*) from public.sq_comp_members m where m.competition_id=c.id),'manager',public.sq_comp_owner(c.id),'joined',exists(select 1 from public.sq_comp_members m where m.competition_id=c.id and m.user_id=auth.uid()),'ownerName',coalesce((select p.data->>'name' from public.documents p where p.collection='profiles' and p.id=c.owner_id::text),'Ustoz')) item
  from public.sq_competitions c where public.sq_comp_read(c.id) order by c.updated_at desc limit 100
 ) rows
$$;

create or replace function public.sq_comp_state(p_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
 declare c public.sq_competitions;s public.sq_comp_stages;m public.sq_comp_members;a public.sq_comp_attempts;manager boolean;teams jsonb;stages jsonb;current jsonb:=null;question jsonb;data jsonb;deadline timestamptz;result jsonb;history jsonb;roster jsonb;
 begin
  if not public.sq_comp_read(p_id) then raise exception 'Musobaqa yopiq yoki sizga tegishli emas';end if;
  select x.* into c from public.sq_competitions x where x.id=p_id;manager:=public.sq_comp_owner(p_id);
  select x.* into m from public.sq_comp_members x where x.competition_id=p_id and x.user_id=auth.uid();
  select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'position',x.position,'title',x.title,'kind',x.kind,'duration',x.duration,'weight',x.weight)||case when manager then jsonb_build_object('config',x.config,'custom',x.data) else '{}' end order by x.position),'[]') into stages from public.sq_comp_stages x where x.competition_id=p_id;
  if c.status='running' then
   select x.* into s from public.sq_comp_stages x where x.competition_id=p_id and x.position=c.current_stage;
   deadline:=c.stage_started_at+make_interval(secs=>s.duration);
   current:=jsonb_build_object('id',s.id,'position',s.position,'title',s.title,'kind',s.kind,'weight',s.weight,'duration',s.duration,'deadline',deadline);
   if m.user_id is not null then
    insert into public.sq_comp_attempts(competition_id,stage_id,user_id,started_at,payload) values(p_id,s.id,auth.uid(),c.stage_started_at,case s.kind when 'maze' then jsonb_build_object('position',s.data->'start','opened','[]'::jsonb,'mistakes','{}'::jsonb,'hints','{}'::jsonb) else '{}'::jsonb end) on conflict(stage_id,user_id) do nothing;
    select x.* into a from public.sq_comp_attempts x where x.stage_id=s.id and x.user_id=auth.uid();
    if a.finished_at is null and (clock_timestamp()>=deadline or m.withdrawn) then update public.sq_comp_attempts x set finished_at=least(clock_timestamp(),deadline),elapsed=greatest(0,extract(epoch from least(clock_timestamp(),deadline)-x.started_at)) where x.stage_id=s.id and x.user_id=auth.uid() returning x.* into a;perform public.sq_comp_tick(p_id);end if;
    data:='{}';
    if a.finished_at is null then
     if s.kind='quiz' then
      question:=s.data->'questions'->a.cursor;
      question:=question-array['correct','answer','acceptedAnswers','officeRubric','criteria'];
      if question?'officeTask' then question:=jsonb_set(question,'{officeTask}',(question->'officeTask')-'rubric');end if;
      data:=jsonb_build_object('question',question,'index',a.cursor,'total',jsonb_array_length(s.data->'questions'));
     elsif s.kind='typing' then data:=s.data;
     else
      select jsonb_agg(t-array['answer','translation','explanation','hints']) into question from jsonb_array_elements(s.data->'tasks') t;
      data:=(s.data-'tasks'-'route')||jsonb_build_object('tasks',question,'position',a.payload->'position','opened',a.payload->'opened','mistakes',a.payload->'mistakes','hintsUsed',a.payload->'hints');
     end if;
    end if;
    current:=current||jsonb_build_object('data',data,'finished',a.finished_at is not null,'score',a.score,'correct',a.correct,'feedback',a.feedback);
   end if;
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('stage',st.position,'title',st.title,'score',at.score,'correct',at.correct,'elapsed',at.elapsed,'finished',at.finished_at is not null) order by st.position),'[]') into history from public.sq_comp_attempts at join public.sq_comp_stages st on st.id=at.stage_id where at.competition_id=p_id and at.user_id=auth.uid();
  if manager then
   select coalesce(jsonb_agg(jsonb_build_object('name',mem.name,'teamId',mem.team_id,'withdrawn',mem.withdrawn,'stages',(select coalesce(jsonb_agg(jsonb_build_object('stage',st.position,'score',at.score,'correct',at.correct,'elapsed',at.elapsed,'finished',at.finished_at is not null,'feedback',at.feedback) order by st.position),'[]') from public.sq_comp_attempts at join public.sq_comp_stages st on st.id=at.stage_id where at.competition_id=p_id and at.user_id=mem.user_id)) order by mem.team_id,mem.seat),'[]') into roster from public.sq_comp_members mem where mem.competition_id=p_id;
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'title',r.title,'joined',r.joined,'score',r.score,'correct',r.correct,'elapsed',r.elapsed,'rank',r.place,'stages',r.stage_rows)||case when manager then jsonb_build_object('code',r.join_code,'roster',r.roster) else '{}' end order by r.place,r.title),'[]') into teams from (
   select t.*,coalesce(stats.joined,0) joined,coalesce(stats.score,0) score,coalesce(stats.correct,0) correct,coalesce(stats.elapsed,0) elapsed,
    rank() over(order by coalesce(stats.score,0) desc,coalesce(stats.correct,0) desc,coalesce(stats.elapsed,0) asc) place,
    (select coalesce(jsonb_agg(jsonb_build_object('position',st.position,'score',coalesce((select round(sum(at.score)/c.team_size,2) from public.sq_comp_attempts at join public.sq_comp_members mem on mem.competition_id=at.competition_id and mem.user_id=at.user_id where at.stage_id=st.id and mem.team_id=t.id),0),'completed',(select count(*) from public.sq_comp_attempts at join public.sq_comp_members mem on mem.competition_id=at.competition_id and mem.user_id=at.user_id where at.stage_id=st.id and mem.team_id=t.id and at.finished_at is not null)) order by st.position),'[]') from public.sq_comp_stages st where st.competition_id=p_id) stage_rows
   from public.sq_comp_teams t left join lateral(
    select (select count(*) from public.sq_comp_members mem where mem.team_id=t.id) joined,round(sum(at.score*st.weight)/c.team_size,2) score,sum(at.correct) correct,round(sum(at.elapsed),2) elapsed
    from public.sq_comp_attempts at join public.sq_comp_stages st on st.id=at.stage_id join public.sq_comp_members mem on mem.competition_id=at.competition_id and mem.user_id=at.user_id where mem.team_id=t.id
   ) stats on true where t.competition_id=p_id
  ) r;
  result:=jsonb_build_object('competition',jsonb_build_object('id',c.id,'title',c.title,'description',c.description,'visibility',c.visibility,'teamSize',c.team_size,'status',c.status,'currentStage',c.current_stage),'manager',manager,'teams',teams,'stages',stages,'current',current,'me',case when m.user_id is not null then jsonb_build_object('name',m.name,'teamId',m.team_id,'seat',m.seat,'withdrawn',m.withdrawn) else null end,'history',history,'serverNow',clock_timestamp());
  if manager then result:=result||jsonb_build_object('members',roster);end if;
  return result;
 end
$$;

create or replace function public.sq_comp_join(p_code text,p_name text) returns jsonb language plpgsql security definer set search_path='' as $$
 declare t public.sq_comp_teams;c public.sq_competitions;seatno integer;name text:=btrim(p_name);
 begin
  if not public.sq_comp_limit('join',10) then return jsonb_build_object('error','Urinishlar ko‘payib ketdi. Bir daqiqadan so‘ng urinib ko‘ring.');end if;
  if length(name) not between 2 and 40 or upper(btrim(p_code)) !~ '^[A-F0-9]{8}$' then return jsonb_build_object('error','Ism va 8 belgili jamoa kodini tekshiring.');end if;
  select x.* into t from public.sq_comp_teams x where x.join_code=upper(btrim(p_code));
  if not found then return jsonb_build_object('error','Jamoa kodi noto‘g‘ri yoki musobaqa yopiq.');end if;
  select x.* into c from public.sq_competitions x where x.id=t.competition_id for update;
  if exists(select 1 from public.sq_comp_members m where m.competition_id=c.id and m.user_id=auth.uid()) then return public.sq_comp_state(c.id);end if;
  if c.status<>'lobby' then return jsonb_build_object('error','Hozir ro‘yxatdan o‘tish ochiq emas.');end if;
  if public.sq_comp_owner(c.id) then return jsonb_build_object('error','Tashkilotchi jamoa tarkibiga kirmaydi. O‘quvchi hisobidan kiring.');end if;
  if jsonb_array_length(t.roster)>0 then
   select ord::integer into seatno from jsonb_array_elements_text(t.roster) with ordinality r(n,ord) where public.sq_comp_norm(n)=public.sq_comp_norm(name) and not exists(select 1 from public.sq_comp_members m where m.team_id=t.id and m.seat=r.ord);
  else
   select n into seatno from generate_series(1,c.team_size) n where not exists(select 1 from public.sq_comp_members m where m.team_id=t.id and m.seat=n) order by n limit 1;
  end if;
  if seatno is null then return jsonb_build_object('error','Jamoa to‘lgan yoki ism ustoz ro‘yxatiga mos emas.');end if;
  if jsonb_array_length(t.roster)>0 then name:=t.roster->>(seatno-1);end if;
  insert into public.sq_comp_members(competition_id,user_id,team_id,seat,name) values(c.id,auth.uid(),t.id,seatno,name);
  perform public.sq_comp_tick(c.id);return public.sq_comp_state(c.id);
 end
$$;

create or replace function public.sq_comp_control(p_id uuid,p_action text,p_expected_stage integer default 0) returns jsonb language plpgsql security definer set search_path='' as $$
 declare c public.sq_competitions;s public.sq_comp_stages;deadline timestamptz;members integer;done integer;total integer;
 begin
  select x.* into c from public.sq_competitions x where x.id=p_id for update;
  if not found or not public.sq_comp_owner(p_id) then raise exception 'Musobaqani boshqarishga ruxsat yo‘q';end if;
  if p_action='publish' then
   if c.status='lobby' then return public.sq_comp_state(p_id);end if;
   if c.status<>'draft' then raise exception 'Bu musobaqa allaqachon faollashtirilgan';end if;
   update public.sq_competitions x set status='lobby',updated_at=clock_timestamp() where x.id=p_id;
  elsif p_action='start' then
   if c.status='running' then return public.sq_comp_state(p_id);end if;
   if c.status<>'lobby' then raise exception 'Avval ro‘yxatdan o‘tishni faollashtiring';end if;
   select count(*) into members from public.sq_comp_members m where m.competition_id=p_id;
   select count(*)*c.team_size into total from public.sq_comp_teams t where t.competition_id=p_id;
   if members<>total then raise exception 'Barcha jamoalar to‘liq bo‘lgach musobaqa boshlanadi';end if;
   update public.sq_competitions x set status='running',current_stage=1,stage_started_at=clock_timestamp(),updated_at=clock_timestamp() where x.id=p_id;
  elsif p_action in ('next','force-next') then
   if c.current_stage>p_expected_stage or c.status='finished' then return public.sq_comp_state(p_id);end if;
   if c.status<>'running' or c.current_stage<>p_expected_stage then raise exception 'Bosqich holati o‘zgargan. Yangilang';end if;
   select x.* into s from public.sq_comp_stages x where x.competition_id=p_id and x.position=c.current_stage;
   deadline:=c.stage_started_at+make_interval(secs=>s.duration);
   select count(*) into members from public.sq_comp_members m where m.competition_id=p_id;
   select count(*) into done from public.sq_comp_attempts a where a.stage_id=s.id and a.finished_at is not null;
   if p_action='next' and clock_timestamp()<deadline and done<members then raise exception 'Hali barcha ishtirokchi tugatmagan. Kuting yoki bosqichni yakunlang';end if;
   insert into public.sq_comp_attempts(competition_id,stage_id,user_id,started_at) select p_id,s.id,m.user_id,c.stage_started_at from public.sq_comp_members m where m.competition_id=p_id on conflict(stage_id,user_id) do nothing;
   update public.sq_comp_attempts a set finished_at=least(clock_timestamp(),deadline),elapsed=greatest(0,extract(epoch from least(clock_timestamp(),deadline)-a.started_at)) where a.stage_id=s.id and a.finished_at is null;
   select count(*) into total from public.sq_comp_stages x where x.competition_id=p_id;
   if c.current_stage>=total then update public.sq_competitions x set status='finished',updated_at=clock_timestamp() where x.id=p_id;
   else update public.sq_competitions x set current_stage=c.current_stage+1,stage_started_at=clock_timestamp(),updated_at=clock_timestamp() where x.id=p_id;end if;
  elsif p_action='cancel' then
   update public.sq_competitions x set status='cancelled',updated_at=clock_timestamp() where x.id=p_id;
   update public.sq_comp_attempts a set finished_at=coalesce(a.finished_at,clock_timestamp()),elapsed=case when a.finished_at is null then greatest(0,extract(epoch from clock_timestamp()-a.started_at)) else a.elapsed end where a.competition_id=p_id;
  else raise exception 'Boshqaruv amali noma’lum';end if;
  perform public.sq_comp_tick(p_id);return public.sq_comp_state(p_id);
 end
$$;

create or replace function public.sq_comp_path(p_data jsonb,p_start jsonb,p_path jsonb,p_opened jsonb,p_target jsonb) returns boolean language plpgsql immutable set search_path='' as $$
 declare prev jsonb:=p_start;v jsonb;x integer;y integer;gate integer;i integer:=0;n integer;
 begin
  if jsonb_typeof(p_path) is distinct from 'array' or jsonb_array_length(p_path) not between 1 and 500 then return false;end if;n:=jsonb_array_length(p_path);
  for v in select e from jsonb_array_elements(p_path) e loop
   i:=i+1;
   if jsonb_typeof(v) is distinct from 'array' or jsonb_array_length(v)<>2 or coalesce(v->>0,'') !~ '^[0-9]{1,2}$' or coalesce(v->>1,'') !~ '^[0-9]{1,2}$' then return false;end if;
   x:=(v->>0)::integer;y:=(v->>1)::integer;
   if i=1 and v<>prev then return false;end if;
   if i>1 and abs(x-(prev->>0)::integer)+abs(y-(prev->>1)::integer)<>1 then return false;end if;
   if y>=jsonb_array_length(p_data->'grid') or x>=length(p_data->'grid'->>y) or substr(p_data->'grid'->>y,x+1,1)='#' then return false;end if;
   select ord::integer-1 into gate from jsonb_array_elements(p_data->'gateCells') with ordinality gates(pos,ord) where pos=v;
   if gate is not null and not p_opened @> jsonb_build_array(gate) and not (i=n and v=p_target) then return false;end if;
   prev:=v;
  end loop;
  return prev=p_target;
 exception when others then return false;
 end
$$;

create or replace function public.sq_comp_answer(p_id uuid,p_stage uuid,p_action uuid,p_data jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
 <<submission>>
 declare c public.sq_competitions;s public.sq_comp_stages;a public.sq_comp_attempts;m public.sq_comp_members;q jsonb;grade jsonb;deadline timestamptz;payload jsonb;feedback jsonb;points numeric;maximum numeric;score numeric;correct integer;cursor integer;elapsed numeric;finished boolean:=false;key text:=p_action::text;gate integer;mistakes integer;hints integer;path jsonb;chars integer;typed text;target text;accuracy numeric;wpm numeric;body jsonb;
 begin
  if auth.uid() is null or length(p_data::text)>22000 then raise exception 'Javob hajmi yoki kirish holati noto‘g‘ri';end if;
  select x.* into c from public.sq_competitions x where x.id=p_id for update;
  select x.* into m from public.sq_comp_members x where x.competition_id=p_id and x.user_id=auth.uid();
  if m.user_id is null or m.withdrawn then raise exception 'Siz bu musobaqada qatnashmayapsiz';end if;
  select x.* into a from public.sq_comp_attempts x where x.stage_id=p_stage and x.user_id=auth.uid() for update;
  if a.actions?key then return public.sq_comp_state(p_id);end if;
  if c.status<>'running' then raise exception 'Bosqich faol emas';end if;
  select x.* into s from public.sq_comp_stages x where x.competition_id=p_id and x.position=c.current_stage;
  if s.id<>p_stage or a.stage_id is null then raise exception 'Joriy bosqichni qayta oching';end if;
  deadline:=c.stage_started_at+make_interval(secs=>s.duration);elapsed:=greatest(0,extract(epoch from clock_timestamp()-a.started_at));
  if a.finished_at is not null or clock_timestamp()>=deadline then return public.sq_comp_state(p_id);end if;
  if not public.sq_comp_limit('answer',120) then return jsonb_build_object('error','Javoblar juda tez yuborildi. Biroz kuting.');end if;
  payload:=a.payload;points:=a.points;score:=a.score;correct:=a.correct;cursor:=a.cursor;
  if p_data->>'mode'='finish' and s.kind<>'maze' then finished:=true;feedback:=jsonb_build_object('message','Bosqich yakunlandi. Javobsiz topshiriqlar uchun ball berilmadi.');
  elsif s.kind='quiz' then
   q:=s.data->'questions'->a.cursor;
   if q->>'id' is distinct from p_data->>'questionId' then raise exception 'Savol almashgan. Sahifani yangilang';end if;
   grade:=public.sq_comp_grade(q,p_data->'answer');points:=points+(q->>'points')::numeric*(grade->>'ratio')::numeric;
   select sum((x->>'points')::numeric) into maximum from jsonb_array_elements(s.data->'questions') x;
   score:=round(100*points/greatest(maximum,1),2);correct:=correct+case when (grade->>'ratio')::numeric=1 then 1 else 0 end;cursor:=cursor+1;finished:=cursor>=jsonb_array_length(s.data->'questions');
   feedback:=grade||jsonb_build_object('message',case when (grade->>'ratio')::numeric=1 then 'To‘g‘ri javob.' when (grade->>'ratio')::numeric>0 then 'Mezonlarning bir qismi bajarildi.' else 'Bu javob mos kelmadi.' end,'explanation',coalesce(q->>'explanation',''),'correctAnswer',case when q->>'type'='test' then q->'options'->>((q->>'correct')::integer) when q->>'type' in ('practical','shortcut','python') then q->>'answer' else null end);
   payload:=payload||jsonb_build_object('responses',coalesce(payload->'responses','[]')||jsonb_build_array(jsonb_build_object('questionId',q->>'id','answer',p_data->'answer','ratio',grade->'ratio')));
  elsif s.kind='typing' then
   target:=s.data->>'text';typed:=coalesce(p_data->>'text','');if length(typed)>8000 then raise exception 'Matn juda uzun';end if;
   select count(*) into chars from generate_series(1,least(length(target),length(typed))) i where substr(target,i,1)=substr(typed,i,1);
   accuracy:=100*chars::numeric/greatest(length(target),length(typed),1);wpm:=chars*12/greatest(elapsed,1);
   score:=round(accuracy*(.75+.25*least(wpm/75,1)),2);correct:=chars;finished:=true;
   feedback:=jsonb_build_object('message','Matn terish yakunlandi. Aniqlik harflarning o‘z o‘rnida mos kelishi bo‘yicha hisoblandi.','accuracy',round(accuracy,1),'wpm',round(wpm,1),'correctChars',chars,'expectedChars',length(target));payload:=jsonb_build_object('text',typed);
  else
   path:=p_data->'path';
   if p_data->>'mode'='finish' then
    if jsonb_array_length(payload->'opened')<>jsonb_array_length(s.data->'tasks') or not public.sq_comp_path(s.data,payload->'position',path,payload->'opened',s.data->'exit') then raise exception 'Chiqish uchun barcha eshiklarni ochib, yo‘lni tugating';end if;
    finished:=true;feedback:=jsonb_build_object('message','Labirintdan chiqdingiz.');payload:=jsonb_set(payload,'{position}',s.data->'exit');
   else
    if coalesce(p_data->>'gate','') !~ '^[0-7]$' then raise exception 'Eshik raqami noto‘g‘ri';end if;gate:=(p_data->>'gate')::integer;
    if gate>=jsonb_array_length(s.data->'tasks') or payload->'opened' @> jsonb_build_array(gate) then raise exception 'Bu eshik ochilgan yoki mavjud emas';end if;
    if not public.sq_comp_path(s.data,payload->'position',path,payload->'opened',s.data->'gateCells'->gate) then raise exception 'Eshikka yurib yetib boring; devordan o‘tib bo‘lmaydi';end if;
    q:=s.data->'tasks'->gate;mistakes:=coalesce(payload->'mistakes'->>gate::text,'0')::integer;hints:=coalesce(payload->'hints'->>gate::text,'0')::integer;
    if p_data->>'mode'='hint' then
     hints:=least(2,hints+1);payload:=jsonb_set(payload,array['hints',gate::text],to_jsonb(hints),true);feedback:=jsonb_build_object('message','Yordam ishlatildi; bu eshik uchun ball kamayadi.','hint',coalesce(q->'hints'->>(hints-1),'Gapdagi yo‘nalish yoki kalit so‘zni ajrating.'));
    elsif p_data->'answer'=q->'answer' then
     points:=points+greatest(.3,1-mistakes*.15-hints*.2);correct:=correct+1;score:=round(100*points/jsonb_array_length(s.data->'tasks'),2);
     payload:=jsonb_set(payload,'{opened}',payload->'opened'||jsonb_build_array(gate));payload:=jsonb_set(payload,'{position}',s.data->'gateCells'->gate);feedback:=jsonb_build_object('message','To‘g‘ri. Eshik ochildi.','correct',true);
    else
     mistakes:=mistakes+1;payload:=jsonb_set(payload,array['mistakes',gate::text],to_jsonb(mistakes),true);feedback:=jsonb_build_object('message','Gapni qayta o‘qib yoki tinglab ko‘ring.','correct',false);
    end if;
   end if;
  end if;
  update public.sq_comp_attempts x set points=submission.points,score=submission.score,correct=submission.correct,cursor=submission.cursor,payload=submission.payload,feedback=submission.feedback,elapsed=submission.elapsed,finished_at=case when submission.finished then clock_timestamp() else null end,actions=x.actions||jsonb_build_object(submission.key,true) where x.stage_id=p_stage and x.user_id=auth.uid();
  perform public.sq_comp_tick(p_id);return public.sq_comp_state(p_id);
 end
$$;

create or replace function public.sq_comp_leave(p_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
 declare c public.sq_competitions;
 begin
  select x.* into c from public.sq_competitions x where x.id=p_id for update;
  if c.status='lobby' then delete from public.sq_comp_members m where m.competition_id=p_id and m.user_id=auth.uid();
  elsif c.status='running' then update public.sq_comp_members m set withdrawn=true where m.competition_id=p_id and m.user_id=auth.uid();update public.sq_comp_attempts a set finished_at=coalesce(a.finished_at,clock_timestamp()),elapsed=greatest(0,extract(epoch from clock_timestamp()-a.started_at)) where a.competition_id=p_id and a.user_id=auth.uid() and a.finished_at is null;end if;
  if c.id is not null then perform public.sq_comp_tick(p_id);end if;return jsonb_build_object('ok',true);
 end
$$;

-- Read-only metadata. No client can write a score, roster, answer key or stage directly.
alter table public.sq_competitions enable row level security;
alter table public.sq_comp_teams enable row level security;
alter table public.sq_comp_members enable row level security;
alter table public.sq_comp_stages enable row level security;
alter table public.sq_comp_attempts enable row level security;
alter table public.sq_comp_templates enable row level security;
alter table public.sq_comp_limits enable row level security;
alter table public.sq_comp_signals enable row level security;
revoke all on public.sq_competitions,public.sq_comp_teams,public.sq_comp_members,public.sq_comp_stages,public.sq_comp_attempts,public.sq_comp_templates,public.sq_comp_limits,public.sq_comp_signals from public,anon,authenticated;
grant select on public.sq_competitions,public.sq_comp_signals to authenticated;
drop policy if exists sq_comp_read_policy on public.sq_competitions;
create policy sq_comp_read_policy on public.sq_competitions for select to authenticated using(public.sq_comp_read(id));
drop policy if exists sq_comp_signal_policy on public.sq_comp_signals;
create policy sq_comp_signal_policy on public.sq_comp_signals for select to authenticated using(public.sq_comp_read(competition_id));
do $$ declare f record;begin
 for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'sq_comp_%' loop execute format('revoke execute on function %s from public,anon,authenticated',f.signature);end loop;
end $$;
grant execute on function public.sq_comp_owner(uuid),public.sq_comp_read(uuid),public.sq_comp_list(),public.sq_comp_catalog(),public.sq_comp_save(uuid,jsonb),public.sq_comp_state(uuid),public.sq_comp_join(text,text),public.sq_comp_control(uuid,text,integer),public.sq_comp_answer(uuid,uuid,uuid,jsonb),public.sq_comp_leave(uuid) to authenticated;
do $$ begin
 if exists(select 1 from pg_publication p where p.pubname='supabase_realtime') and not exists(select 1 from pg_publication_tables p where p.pubname='supabase_realtime' and p.schemaname='public' and p.tablename='sq_comp_signals') then alter publication supabase_realtime add table public.sq_comp_signals;end if;
end $$;

