###","#..S#.........#.#.#.#","#.###########.#.#.#.#","#.........#...#.....#","###.#.###.#.#.#.#####","#M..#.#.#...#.......#","#####.#.#.###.###.#.#","#.#.#...#.#.#...#.#.#","#.#.#######.###.###.#","#.................#.#","###.###.###.#########","#.#.#.....#...#.....#","#.#.#####.###.###.###","#...#.....#.....#.#.#","#.###.###.#.###.#.#.#","#.#...#.#.#.#.......#","###.#.#.###.###.###.#","#E..#.....#.#...#...#","#####################"],"start":[3,1],"exit":[1,17],"monster":[1,5],"route":[[3,1],[1,1],[1,3],[3,3],[5,3],[7,3],[9,3],[9,5],[11,5],[11,3],[13,3],[13,5],[13,7],[15,7],[15,9],[13,9],[11,9],[9,9],[7,9],[7,11],[9,11],[9,13],[7,13],[5,13],[5,15],[3,15],[3,17],[1,17]],"gateCells":[[3,3],[9,5],[13,3],[15,9],[9,9],[9,11],[5,15]],"mapSource":"SinfQuiz separately authored fixed layout; see source note in AUDIO-MAZE.md","distance":27,"taskCount":7,"tasks":[{"id":"b1-01","audio":"Excuse me, how do I reach the library? Go across the courtyard and turn right after the statue.","translation":"Kechirasiz, kutubxonaga qanday boraman? Hovlidan o‘ting va haykaldan keyin o‘ngga buriling.","options":["Haykaldan oldin chapga","Haykaldan keyin o‘ngga","Hovliga qayting"],"answer":1,"explanation":"Yo‘nalish haykaldan keyin o‘ngga.","hints":["Suhbatdagi “after the statue” qismini aniqlang.","After — keyin; turn right — o‘ngga buriling."],"skill":"dialogue"},{"id":"b1-03","audio":"Keep going until you see a narrow passage between the bakery and the post office.","translation":"Nonvoyxona va pochta orasidagi tor yo‘lakni ko‘rguncha davom eting.","options":["Tor yo‘lak","Keng zinapoya","Yashil darvoza"],"answer":0,"explanation":"Muhim belgi — ikki bino orasidagi tor yo‘lak.","hints":["“Until you see” dan keyingi tasvirni tuting.","Narrow passage — tor yo‘lak."],"skill":"instruction"},{"id":"b1-05","audio":"Walk east to the bridge. Before crossing it, follow the path that bends south.","translation":"Sharqqa ko‘prikkacha yuring. Undan o‘tishdan oldin janubga egiladigan yo‘lakka kiring.","options":["Ko‘prikdan o‘tib shimolga","Ko‘prikdan oldin janubga burilgan yo‘l","Sharqqa qaytish"],"answer":1,"explanation":"Ko‘prikdan o‘tmay, oldin janubga burilasiz.","hints":["“Before crossing” muhim vaqt belgisidir.","Before crossing — o‘tishdan oldin."],"skill":"instruction"},{"id":"b1-07","audio":"At the crossroads, ignore the path with the red flags and take the one marked with two blue circles.","translation":"Chorrahada qizil bayroqli yo‘lni olmang; ikkita ko‘k doira bilan belgilanganiga kiring.","options":["Qizil bayroqli yo‘l","Ikkita ko‘k doirali yo‘l","Bitta ko‘k doirali yo‘l"],"answer":1,"explanation":"Qizil bayroqli yo‘l rad etilgan; ikkita ko‘k doirali yo‘l to‘g‘ri.","hints":["“Ignore” bu yo‘lni tanlamaslikni bildiradi.","Two blue circles — ikkita ko‘k doira."],"skill":"symbol"},{"id":"b1-09","audio":"Take the corridor on the left. When it splits, choose the branch with the brighter lights.","translation":"Chap yo‘lakka kiring. U ikkiga ajralganda yorug‘roq chiroqli tarmoqni tanlang.","options":["Chapga, so‘ng yorug‘ tarmoqqa","O‘ngga, so‘ng qorong‘i yo‘lga","Chapga, so‘ng orqaga"],"answer":0,"explanation":"Ikkinchi tanlov yorug‘roq yo‘l.","hints":["Gapda ikkita ketma-ket ko‘rsatma bor.","Splits — ikkiga ajraladi; brighter — yorug‘roq."],"skill":"sequence"},{"id":"b1-11","audio":"Go down the steps, pass the first blue door, and enter the second blue door.","translation":"Zinadan tushing, birinchi ko‘k eshikdan o‘ting va ikkinchi ko‘k eshikka kiring.","options":["Birinchi ko‘k eshik","Ikkinchi ko‘k eshik","Zinaga qayting"],"answer":1,"explanation":"Eshiklar bir xil rangda, farq tartibida.","hints":["Birinchi va ikkinchi tartib sonini adashtirmang.","Second — ikkinchi."],"skill":"sequence"},{"id":"b1-01","audio":"Excuse me, how do I reach the library? Go across the courtyard and turn right after the statue.","translation":"Kechirasiz, kutubxonaga qanday boraman? Hovlidan o‘ting va haykaldan keyin o‘ngga buriling.","options":["Haykaldan oldin chapga","Haykaldan keyin o‘ngga","Hovliga qayting"],"answer":1,"explanation":"Yo‘nalish haykaldan keyin o‘ngga.","hints":["Suhbatdagi “after the statue” qismini aniqlang.","After — keyin; turn right — o‘ngga buriling."],"skill":"dialogue"}]}},{"id":"maze:maze-10","kind":"maze","title":"Qadimiy qal’a","data":{"id":"maze-10","title":"Qadimiy qal’a","difficulty":"hard","grid":["#####################","#.....#...#.#.....#.#","#.#.###.#.#.#####.#.#","#.#.....#.#.#.......#","###.#.#####.###.###.#","#...#.#.....#.....#.#","#.#####.###.#.#.#####","#.........#...#.#...#","#####.#####.###.#.###","#.#.......#...#.....#","#.#.#####.###.#######","#.......#.#...#....S#","#.###.#####.#.#.#####","#...#...#...#.......#","###.#.#.#####.#.#.#.#","#...#.#.#...#M#.#.#.#","###.#####.###.#######","#.......#...#.#.....#","#.###.#.#.#######.#.#","#.#...#...........#E#","#####################"],"start":[19,11],"exit":[19,19],"monster":[13,15],"route":[[19,11],[17,11],[15,11],[15,13],[13,13],[13,11],[13,9],[11,9],[11,7],[11,5],[9,5],[7,5],[7,7],[5,7],[5,9],[3,9],[3,11],[1,11],[1,13],[3,13],[3,15],[3,17],[5,17],[7,17],[7,19],[9,19],[11,19],[13,19],[15,19],[17,19],[17,17],[19,17],[19,19]],"gateCells":[[13,13],[11,7],[7,7],[3,11],[3,15],[7,19],[15,19]],"mapSource":"SinfQuiz separately authored fixed layout; see source note in AUDIO-MAZE.md","distance":32,"taskCount":7,"tasks":[{"id":"b1-04","audio":"I left my red umbrella on the chair near the window, not on the table.","translation":"Qizil soyabonimni deraza yonidagi stulga qoldirdim, stolga emas.","options":["Deraza yonidagi stul","Stol","Eshik oldi"],"answer":0,"explanation":"Stol varianti “not” bilan rad etilgan.","hints":["Buyum, rang va joylashuvni birga yodda tuting.","Near the window — deraza yonida."],"skill":"dialogue"},{"id":"b1-06","audio":"The caretaker says the spare key is underneath the third flowerpot from the door.","translation":"Qorovul zaxira kalit eshikdan sanaganda uchinchi gul tuvagi tagida ekanini aytadi.","options":["Birinchi tuvak","Uchinchi tuvak","To‘rtinchi tuvak"],"answer":1,"explanation":"Eshikdan sanaganda uchinchi tuvak.","hints":["Boshlanish nuqtasi eshik ekanini unutmang.","Third — uchinchi; underneath — tagida."],"skill":"number"},{"id":"b1-08","audio":"Mina: Is the exit beside the clock? Omar: No, it is just beyond the second arch.","translation":"Mina: Chiqish soat yonidami? Omar: Yo‘q, u ikkinchi ravoqdan sal narida.","options":["Soat yonida","Birinchi ravoqdan oldin","Ikkinchi ravoqdan keyin"],"answer":2,"explanation":"Omar “No” deb tuzatadi: ikkinchi ravoqdan keyin.","hints":["Javob beruvchining tuzatishini tinglang.","Beyond — narigi tomonida/keyin."],"skill":"dialogue"},{"id":"b1-10","audio":"The green door will stay locked until you bring the small silver key from the fountain.","translation":"Favvoradan kichik kumush kalitni olib kelmaguningizcha yashil eshik qulfligicha qoladi.","options":["Katta oltin kalit","Kichik kumush kalit","Ko‘k karta"],"answer":1,"explanation":"Kalit kichik va kumush rangda, favvora yonidan olinadi.","hints":["“Until” dan keyingi shartni eshiting.","Silver — kumush; until — ...guncha."],"skill":"dialogue"},{"id":"b1-12","audio":"The guide says the exit is behind the stage, although the map shows it beside the stage.","translation":"Yo‘lboshchi chiqish sahna orqasida deydi, xaritada esa yonida ko‘rsatilgan.","options":["Sahna yonida","Sahna orqasida","Sahna oldida"],"answer":1,"explanation":"Savolda yo‘lboshchining aytganini topish kerak.","hints":["“Although” xaritadagi farqli ma’lumotni kiritadi.","Behind — orqasida."],"skill":"dialogue"},{"id":"b1-02","audio":"The yellow sign is not at the entrance; it is opposite the water fountain.","translation":"Sariq belgi kirishda emas, suv favvorasining ro‘parasida.","options":["Kirishda","Favvora ro‘parasida","Favvora tagida"],"answer":1,"explanation":"“Opposite” — ro‘parasida.","hints":["Avvalgi joy inkor qilinadi, keyin to‘g‘risi aytiladi.","Opposite — ro‘parasida."],"skill":"place"},{"id":"b1-04","